create type public.user_role as enum ('user','editor','admin');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, role public.user_role not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.anime(id bigint primary key, title text not null, title_native text, slug text unique not null, cover_url text not null, banner_url text, description text, score numeric(4,1), status text, format text, episodes integer, genres text[] not null default '{}', anilist_id bigint unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.episodes(id uuid primary key default gen_random_uuid(), anime_id bigint not null references public.anime(id) on delete cascade, number integer not null, title text, thumbnail_url text, duration_seconds integer, created_at timestamptz not null default now(), unique(anime_id,number));
create table public.episode_sources(id uuid primary key default gen_random_uuid(), episode_id uuid not null references public.episodes(id) on delete cascade, name text not null, url text not null, quality text, kind text not null default 'hls', subtitles jsonb not null default '[]', priority integer not null default 100, enabled boolean not null default true);
create table public.media_assets(id uuid primary key default gen_random_uuid(), path text not null unique, public_url text not null, alt text, mime_type text, width integer, height integer, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.home_banners(id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text not null, anime_id bigint references public.anime(id) on delete set null, href text, sort_order integer not null default 0, enabled boolean not null default true, created_at timestamptz not null default now());
create table public.favorites(user_id uuid references auth.users(id) on delete cascade, anime_id bigint references public.anime(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,anime_id));
create table public.watch_history(user_id uuid references auth.users(id) on delete cascade, episode_id uuid references public.episodes(id) on delete cascade, position_seconds integer not null default 0, duration_seconds integer not null default 0, updated_at timestamptz not null default now(), primary key(user_id,episode_id));
create index anime_genres_idx on public.anime using gin(genres); create index episodes_anime_idx on public.episodes(anime_id); create index banners_order_idx on public.home_banners(enabled,sort_order);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','editor')); $$;
alter table public.profiles enable row level security; alter table public.anime enable row level security; alter table public.episodes enable row level security; alter table public.episode_sources enable row level security; alter table public.media_assets enable row level security; alter table public.home_banners enable row level security; alter table public.favorites enable row level security; alter table public.watch_history enable row level security;
create policy "public read anime" on public.anime for select using(true); create policy "public read episodes" on public.episodes for select using(true); create policy "public read sources" on public.episode_sources for select using(enabled=true); create policy "public read banners" on public.home_banners for select using(enabled=true); create policy "own profile" on public.profiles for select using(id=auth.uid()); create policy "own favorites" on public.favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own history" on public.watch_history for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "staff anime" on public.anime for all using(public.is_staff()) with check(public.is_staff()); create policy "staff episodes" on public.episodes for all using(public.is_staff()) with check(public.is_staff()); create policy "staff sources" on public.episode_sources for all using(public.is_staff()) with check(public.is_staff()); create policy "staff media" on public.media_assets for all using(public.is_staff()) with check(public.is_staff()); create policy "staff banners" on public.home_banners for all using(public.is_staff()) with check(public.is_staff());
insert into storage.buckets(id,name,public) values('koon-media','koon-media',true) on conflict(id) do nothing;
create policy "public media read" on storage.objects for select using(bucket_id='koon-media'); create policy "staff media upload" on storage.objects for insert with check(bucket_id='koon-media' and public.is_staff()); create policy "staff media update" on storage.objects for update using(bucket_id='koon-media' and public.is_staff()); create policy "staff media delete" on storage.objects for delete using(bucket_id='koon-media' and public.is_staff());
create policy "staff read profiles" on public.profiles for select using(public.is_staff());
